num     p s = TokenNum s 

assign  p s = TokenAssign 

oplus   p s = TokenPlus 

ominus  p s = TokenMinus 

otimes  p s = TokenTimes 

odiv    p s = TokenDiv 

ob      p s = TokenOB 

